import { z } from "zod";

/**
 * LaMill's one privacy policy for every browser extension — data contract.
 *
 * `src/content/privacy.json` is generated by Tabmill from its
 * `privacy-policy.yaml` (README.md § Extensions privacy contract). Tabmill's
 * release lint refuses to ship an extension that does more than this policy
 * covers, and checks the live page shows the current `version`.
 */
export const privacySchema = z.object({
  /** Bumped whenever what the policy promises changes. Shown as "Policy version N". */
  version: z.number().int().positive(),
  updated: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  /** Every permission a LaMill extension may request → plain-language reason. */
  permissions: z.record(z.string()),
});
export type PrivacyPolicy = z.infer<typeof privacySchema>;

const files = import.meta.glob("../content/privacy.json", { eager: true, import: "default" });

function load(): PrivacyPolicy | undefined {
  const raw = Object.values(files)[0];
  if (raw === undefined) return undefined;
  const parsed = privacySchema.safeParse(raw);
  if (!parsed.success) {
    console.error("[privacy] invalid privacy.json:", parsed.error.flatten());
    return undefined;
  }
  return parsed.data;
}

const POLICY = load();

export function getPrivacyPolicy(): PrivacyPolicy | undefined {
  return POLICY;
}
